use dioxus::prelude::*;
use dioxus_ix::*;

#[component]
pub fn HostPagedGridPreview() -> Element {
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        IxTheme { class:"host-paged-grid-review",
            gallery_host::HostPagedGridExample {}
            div { onmounted:move |_| {
                #[cfg(all(feature="desktop",not(target_arch="wasm32")))]
                {let window=window.clone();spawn(async move {
                    let query=crate::dom_query::eval(NATIVE_HOST_GRID_CHECK);let _=query.send("hostgrid");
                    match query.join::<serde_json::Value>().await {
                        Ok(value)if value["ok"]==true=>{println!("Dioxus native Host grid: {value}");window.close();}
                        value=>{eprintln!("Dioxus native Host grid failed: {value:?}");std::process::exit(1);}
                    }
                });spawn(async move {futures_timer::Delay::new(std::time::Duration::from_secs(40)).await;eprintln!("Host grid native replay timed out");std::process::exit(1);});}
            } }
        }
    }
}
